import { handle } from '@hono/node-server/vercel'
// @ts-ignore — generated by `npm run vercel-build`
import { app } from '../dist/vercel-app.mjs'

const honoHandler = handle(app)

export default function handler(req: any, res: any) {
  if (req?.url) {
    try {
      const parsed = new URL(req.url, 'http://localhost')
      const vpath = parsed.searchParams.get('__vpath')
      if (vpath !== null) {
        parsed.searchParams.delete('__vpath')
        const cleanPath = '/' + vpath.replace(/^\/+/, '')
        const qs = parsed.searchParams.toString()
        req.url = qs ? `${cleanPath}?${qs}` : cleanPath
      }
    } catch {
      // Keep original req.url if URL parsing fails
    }
  }
  return honoHandler(req, res)
}
